<?php
require_once __DIR__ . '/../includes/auth.php';$u=require_role(['user']);if(isset($_GET['read'])){$id=(int)$_GET['read'];$pdo->prepare("UPDATE notifications SET is_read=1,read_at=NOW() WHERE id=? AND recipient_id=?")->execute([$id,$u['id']]);redirect('notifications.php');}$s=$pdo->prepare("SELECT * FROM notifications WHERE recipient_id=? ORDER BY created_at DESC");$s->execute([$u['id']]);$rows=$s->fetchAll();page_header('Notifications');?><h1>My Notifications</h1><div class="panel"><div class="panel-body"><?php foreach($rows as $n):?><div class="notice"><strong><?=e($n['notification_type'])?></strong> · <?=e($n['created_at'])?><p><?=e($n['message'])?></p><?php if(!$n['is_read']):?><a href="?read=<?=$n['id']?>">Mark as read</a><?php else:?><span class="muted">Read</span><?php endif;?></div><?php endforeach;?><?php if(!$rows):?>No notifications yet.<?php endif;?></div></div><?php page_footer();?>
